// Window — Adw.Window
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles window with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface WindowProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Adw.Window */
  adaptivePreview?: boolean

  /** Application, from Gtk.Window */
  application?: ReactNode

  /** Widget, from Gtk.Window */
  child?: ReactNode

  /** Gtk.Widget, from Adw.Window */
  content?: ReactNode

  /** gboolean, from Gtk.Window */
  decorated?: boolean

  /** gint, from Gtk.Window */
  defaultHeight?: number

  /** Widget, from Gtk.Window */
  defaultWidget?: ReactNode

  /** gint, from Gtk.Window */
  defaultWidth?: number

  /** gboolean, from Gtk.Window */
  deletable?: boolean

  /** gboolean, from Gtk.Window */
  destroyWithParent?: boolean

  /** Gdk.Display, from Gtk.Window */
  display?: ReactNode

  /** gboolean, from Gtk.Window */
  focusVisible?: boolean

  /** Widget, from Gtk.Window */
  focusWidget?: ReactNode

  /** gboolean, from Gtk.Window */
  fullscreened?: boolean

  /** WindowGravity, from Gtk.Window */
  gravity?: ReactNode

  /** gboolean, from Gtk.Window */
  handleMenubarAccel?: boolean

  /** gboolean, from Gtk.Window */
  hideOnClose?: boolean

  /** utf8, from Gtk.Window */
  iconName?: string

  /** gboolean, from Gtk.Window */
  maximized?: boolean

  /** gboolean, from Gtk.Window */
  mnemonicsVisible?: boolean

  /** gboolean, from Gtk.Window */
  modal?: boolean

  /** gboolean, from Gtk.Window */
  resizable?: boolean

  /** utf8, from Gtk.Window */
  startupId?: string

  /** utf8, from Gtk.Window */
  title?: string

  /** Widget, from Gtk.Window */
  titlebar?: ReactNode

  /** Window, from Gtk.Window */
  transientFor?: ReactNode
}

export function Window({ className, children, title }: WindowProps) {
  return (
    <div className={cn(className)}>
      {title}
      {children}
    </div>
  )
}
